from collections import deque
R=C=16
seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]!=7 and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c)); comp=[]
   while q:
    x,y=q.pop();comp.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     a,b=x+dx,y+dy
     if 0<=a<R and 0<=b<C and grid[a][b]!=7 and (a,b) not in seen:
      seen.add((a,b));q.append((a,b))
   comps.append(comp)
[(len(co), (min(r for r,c in co),max(r for r,c in co),min(c for r,c in co),max(c for r,c in co)), sorted(set(grid[r][c] for r,c in co)-{0})) for co in comps]

key={9,5,1}
out=[row[:] for row in grid]
cleared=[]
for co in comps:
 vals=set(grid[r][c] for r,c in co)-{0,7}
 # avoid the top-left legend component (which contains the 3 frame)
 if vals and key <= vals and not any(grid[r][c]==3 for r,c in co):
  cleared.append((len(co),vals,(min(r for r,c in co),max(r for r,c in co),min(c for r,c in co),max(c for r,c in co))))
  for r,c in co: out[r][c]=7
cleared, '\n'.join(' '.join(map(str,r)) for r in out)
